#!/usr/bin/env bash
# moe_train_eval.sh — MoE-as-fast-generator experiment, TRAIN stage.
#
# Trains the mission 31B dense on verified traces GENERATED BY the fast 26B-A4B MoE
# on easy tasks (cross-model 26B->31B; see moe_collect/README.md for the full design,
# eval arms and gating criteria).
#
# Frees the .20 trainer first (RTX 8000 = the certified trainer: one 48GB card holds
# the whole 4-bit 31B, no device_map naive-pipeline waste), then restores it.
#
# NOTE: this script's NAME is matched by fleet_supervisor.sh:experiment_active(), so
# while it runs the supervisor DEFERS collection (won't relaunch the workers we stop)
# but still reaps zombies. That is the designed seam — not a kill switch.
set -u
SD=/data3/tbench_local/frontier/selfdistill
CL="$SD/cluster"
OUT="$SD/moe_collect"
LOG="$OUT/train.log"
PY_TRAIN=/data3/compass/.venv-train/bin/python
PYT=/home/bobef/miniconda3/bin/python3
MODEL_HF=/data3/Models/gemma-4-31B-it-hf
LLAMA=/data3/build/llama.cpp
T20=bobef@192.168.50.20
TRAIN_STEPS="${TRAIN_STEPS:-60}"
TRAIN_SEQ="${TRAIN_SEQ:-1024}"     # .20's 48GB card fits seq-1024 (vs .22's 512 OOM)
MIN_TRAJ="${MIN_TRAJ:-12}"         # refuse to train on a too-small corpus
say(){ echo "[$(date '+%F %T')] $*" | tee -a "$LOG"; }
ssh20(){ timeout "${1:-600}" ssh -o StrictHostKeyChecking=no -o ConnectTimeout=10 "$T20" "$2"; }

# ── 1. preconditions ─────────────────────────────────────────────────────────
n_traj=$(ls "$OUT"/*_solved_traj.json 2>/dev/null | wc -l)
say "corpus: $n_traj MoE solve-trajectories"
if [ "$n_traj" -lt "$MIN_TRAJ" ]; then
  say "ABORT: only $n_traj trajectories (< MIN_TRAJ=$MIN_TRAJ). Heredity memorized at 16-31;"
  say "       training on fewer just re-runs that failure. Grow the corpus first."
  exit 1
fi

# ── 2. harvest -> SFT via the CANONICAL path (re-key/window/clean) ───────────
SFT="$OUT/moe_tbench_sft.jsonl"
say "harvest-tbench over $n_traj trajectories -> $SFT"
( cd /data3/compass && "$PY_TRAIN" -m compass harvest-tbench --traj-dir "$OUT" --out "$SFT" ) >>"$LOG" 2>&1 \
  || { say "ABORT: harvest failed"; exit 1; }
rows=$(grep -c . "$SFT" 2>/dev/null || echo 0)
[ "$rows" -eq 0 ] && { say "ABORT: 0 SFT rows"; exit 1; }
# LEAKAGE GATE — never train on benchmark canaries.
if grep -q "terminal-bench-canary\|sandbox-canary" "$SFT"; then
  say "ABORT: canary leak in SFT — refusing to train"; exit 1
fi
say "SFT rows=$rows (canary-clean)"

# ── 3. free the .20 trainer (stop its 2 workers, then its server) ────────────
# Workers are killed by TMUX SESSION (never `pkill -f <pat>` — a pattern matching our
# own cmdline self-kills; that land-mine is logged in RESUME).
for w in 20a 20b; do
  if tmux has-session -t "wrk_$w" 2>/dev/null; then
    tmux kill-session -t "wrk_$w" && say "stopped worker $w"
  fi
done
say "stopping .20 llama.cpp server (frees the 48GB card for training)"
ssh20 120 'docker stop llamacpp-gemma4-31b' >>"$LOG" 2>&1 || say "WARN: .20 server stop returned non-zero"

restore(){   # always put the box back the way we found it
  say "RESTORE: restarting .20 server"
  ssh20 180 'docker start llamacpp-gemma4-31b' >>"$LOG" 2>&1 || say "WARN: .20 server restart failed"
  say "RESTORE: workers relaunch on the supervisor's next tick (*/10) once this script exits"
}
trap restore EXIT

# ── 4. train the 31B on .20 ──────────────────────────────────────────────────
STAMP=$(date +%Y%m%d-%H%M)
ADAPTER="/data3/compass/adapters/moe-easy-$STAMP"
say "copying SFT to .20 (separate local disk)"
scp -o StrictHostKeyChecking=no "$SFT" "$T20:/tmp/moe_sft.jsonl" >>"$LOG" 2>&1 \
  || { say "ABORT: scp failed"; exit 1; }
say "TRAIN on .20: QLoRA steps=$TRAIN_STEPS seq=$TRAIN_SEQ -> $ADAPTER"
ssh20 21600 "cd /data3/compass && PYTORCH_CUDA_ALLOC_CONF=expandable_segments:True \
  $PY_TRAIN -u -m compass train --model $MODEL_HF --data /tmp/moe_sft.jsonl \
  --mode sft --load-4bit --steps $TRAIN_STEPS --seq $TRAIN_SEQ --out $ADAPTER" >>"$LOG" 2>&1 \
  || { say "TRAIN FAILED"; exit 1; }
say "TRAIN done -> $ADAPTER (on .20)"

# ── 5. convert LoRA -> gguf (for llama.cpp serving in the eval) ──────────────
GGUF="/data3/Models/moe-easy-$STAMP-lora.gguf"
say "converting adapter -> $GGUF"
ssh20 3600 "PYTHONPATH=$LLAMA/gguf-py $PYT $LLAMA/convert_lora_to_gguf.py $ADAPTER \
  --base $MODEL_HF --outfile $GGUF --outtype f16" >>"$LOG" 2>&1 \
  || { say "CONVERT FAILED"; exit 1; }
say "DONE: adapter=$ADAPTER gguf=$GGUF (both on .20)"
say "NEXT: eval 3 arms vs moe_collect/eval_splits.json —"
say "  generalization (35 tasks the 31B FAILS) · regression (54 it PASSES) · self-trace control"
